30	/**
31	 * Simple JavaBean domain object representing an owner.
32	 *
33	 * @author Ken Krebs
34	 * @author Juergen Hoeller
35	 * @author Sam Brannen
36	 * @author Michael Isvy
37	 */
38	@Entity
39	@Table(name = "owners")
40	public class Owner extends Person {
41	
42	    @Column(name = "title")
43	    private String title;
44	
45	    @Column(name = "address")
46	    @NotEmpty
47	    private String address;
48	
49	    @Column(name = "address_line1")
50	    private String addressLine1;
51	
52	    @Column(name = "address_line2")
53	    private String addressLine2;
54	
55	    @Column(name = "city")
56	    @NotEmpty
57	    private String city;
58	
59	    @Column(name = "telephone")
60	    @NotEmpty
61	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Telephone must be in E.164 form (a leading '+' and 8 to 15 digits)")
62	    private String telephone;
63	
64	    @Column(name = "email")
65	    @Email
66	    private String email;
67	
68	    @Column(name = "registration_date")
69	    private LocalDate registrationDate;
70	
71	    @Column(name = "birth_date")
72	    private LocalDate birthDate;
73	
74	    @Column(name = "customer_code")
75	    private String customerCode;
76	
77	    @Column(name = "household_id")
78	    private String householdId;
79	
80	    @Column(name = "namesake_count")
81	    private Integer namesakeCount;
82	
83	    @Column(name = "postcode")
84	    private String postcode;
85	
86	    /**
87	     * Whether this owner was flagged as a suspected soft-duplicate of an existing owner. Retained
88	     * as part of the API/persistence contract but always {@code false} under the current
89	     * household-keyed rule: an owner sharing an existing owner's {@code lastName} and
90	     * {@code postcode} is now the same household, so it is either rejected as a household duplicate
91	     * (409) or admitted as a declared {@code sharesHousehold} member — and a declared member is not
92	     * a suspected duplicate. No production code path sets this field.
93	     */
94	    @Column(name = "possible_duplicate")
95	    private boolean possibleDuplicate;
96	
97	    /**
98	     * The id of the existing owner this owner soft-matches, set together with
99	     * {@link #isPossibleDuplicate()}. Retained for contract compatibility but always {@code null}
100	     * under the current household-keyed rule (see {@link #isPossibleDuplicate()}); no production
101	     * code path sets it.
102	     */
103	    @Column(name = "possible_duplicate_of")
104	    private Integer possibleDuplicateOf;
105	
106	    /**
107	     * Whether this owner has been soft-deleted. A newly created owner is {@code false}; deleting an
108	     * owner (DELETE /api/owners/{id}) flags this {@code true} and retains the row instead of removing
109	     * it. Deleted owners are ignored by the create endpoint's duplicate and identity checks.
110	     */
111	    @Column(name = "deleted")
112	    private boolean deleted;
113	
114	    /**
115	     * Write-only, non-persistent acknowledgement that this owner deliberately shares a
116	     * household with an existing owner. When {@code true}, creation is allowed even if
117	     * another owner already has the same lastName and address.
118	     */
119	    @Transient
120	    private boolean sharesHousehold;
121	
122	    /**
123	     * Read-only, non-persistent count of the owners that share this owner's {@code householdId}
124	     * (including this owner), populated by the service when an owner is loaded for presentation.
125	     * Zero when the owner belongs to no household. Used to derive the membership tier.
126	     */
127	    @Transient
128	    private int householdSize;
129	
130	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
131	    private Set<Pet> pets;
132	
133	    public String getTitle() {
134	        return this.title;
135	    }
136	
137	    public void setTitle(String title) {
138	        this.title = title;
139	    }
140	
141	    /**
142	     * The owner's salutation: the {@link #getTitle() title} and {@code lastName} separated by a
143	     * single space (e.g. {@code "DR Franklin"}), or just the {@code lastName} when the owner has no
144	     * title (title null or empty).
145	     */
146	    public String getSalutation() {
147	        if (this.title == null || this.title.isEmpty()) {
148	            return this.getLastName();
149	        }
150	        return this.title + " " + this.getLastName();
151	    }
152	
153	    public String getAddress() {
154	        return this.address;
155	    }
156	
157	    public void setAddress(String address) {
158	        this.address = address;
159	    }
160	
161	    public String getAddressLine1() {
162	        return this.addressLine1;
163	    }
164	
165	    public void setAddressLine1(String addressLine1) {
166	        this.addressLine1 = addressLine1;
167	    }
168	
169	    public String getAddressLine2() {
170	        return this.addressLine2;
171	    }
172	
173	    public void setAddressLine2(String addressLine2) {
174	        this.addressLine2 = addressLine2;
175	    }
176	
177	    public String getCity() {
178	        return this.city;
179	    }
180	
181	    public void setCity(String city) {
182	        this.city = city;
183	    }
184	
185	    public String getTelephone() {
186	        return this.telephone;
187	    }
188	
189	    public void setTelephone(String telephone) {
190	        this.telephone = telephone;
191	    }
192	
193	    /**
194	     * The stored E.164 {@link #getTelephone() telephone} formatted for human display: the
195	     * country code, a space, then the national digits grouped in threes (e.g.
196	     * {@code "+61 412 345 678"}). Null when no telephone is set.
197	     */
198	    public String getTelephoneDisplay() {
199	        return E164Telephone.toDisplay(this.telephone);
200	    }
201	
202	    public String getEmail() {
203	        return this.email;
204	    }
205	
206	    public void setEmail(String email) {
207	        this.email = email;
208	    }
209	
210	    public LocalDate getRegistrationDate() {
211	        return this.registrationDate;
212	    }
213	
214	    public void setRegistrationDate(LocalDate registrationDate) {
215	        this.registrationDate = registrationDate;
216	    }
217	
218	    public LocalDate getBirthDate() {
219	        return this.birthDate;
220	    }
221	
222	    public void setBirthDate(LocalDate birthDate) {
223	        this.birthDate = birthDate;
224	    }
225	
226	    /**
227	     * The owner's age band derived from {@code birthDate} measured against {@code registrationDate}:
228	     * {@code "MINOR"} when under 18, {@code "ADULT"} from 18 to 64, and {@code "SENIOR"} at 65 or
229	     * over. Returns null when either the birth date or the registration date is not set.
230	     */
231	    public String getAgeBand() {
232	        if (this.birthDate == null || this.registrationDate == null) {
233	            return null;
234	        }
235	        int age = Period.between(this.birthDate, this.registrationDate).getYears();
236	        if (age < 18) {
237	            return "MINOR";
238	        }
239	        if (age < 65) {
240	            return "ADULT";
241	        }
242	        return "SENIOR";
243	    }
244	
245	    public String getCustomerCode() {
246	        return this.customerCode;
247	    }
248	
249	    public void setCustomerCode(String customerCode) {
250	        this.customerCode = customerCode;
251	    }
252	
253	    public String getHouseholdId() {
254	        return this.householdId;
255	    }
256	
257	    public void setHouseholdId(String householdId) {
258	        this.householdId = householdId;
259	    }
260	
261	    public Integer getNamesakeCount() {
262	        return this.namesakeCount;
263	    }
264	
265	    public void setNamesakeCount(Integer namesakeCount) {
266	        this.namesakeCount = namesakeCount;
267	    }
268	
269	    public String getPostcode() {
270	        return this.postcode;
271	    }
272	
273	    public void setPostcode(String postcode) {
274	        this.postcode = postcode;
275	    }
276	
277	    public boolean isPossibleDuplicate() {
278	        return this.possibleDuplicate;
279	    }
280	
281	    public void setPossibleDuplicate(boolean possibleDuplicate) {
282	        this.possibleDuplicate = possibleDuplicate;
283	    }
284	
285	    public Integer getPossibleDuplicateOf() {
286	        return this.possibleDuplicateOf;
287	    }
288	
289	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
290	        this.possibleDuplicateOf = possibleDuplicateOf;
291	    }
292	
293	    public boolean isDeleted() {
294	        return this.deleted;
295	    }
296	
297	    public void setDeleted(boolean deleted) {
298	        this.deleted = deleted;
299	    }
300	
301	    /** The household size at or above which an owner earns the household membership points. */
302	    public static final int MEMBERSHIP_HOUSEHOLD_SIZE = 3;
303	
304	    /** The month (1 July) on which the fiscal year begins. */
305	    public static final int FISCAL_YEAR_START_MONTH = 7;
306	
307	    /**
308	     * The number of elapsed fiscal years at or above which an owner earns the tenure membership
309	     * points.
310	     */
311	    public static final long MEMBERSHIP_TENURE_FISCAL_YEARS = 1;
312	
313	    /**
314	     * The fiscal year (as a full four-digit number) that {@code date} falls in, where the fiscal
315	     * year begins on 1 July and is labelled by the calendar year in which it ends: a date on or
316	     * after 1 July belongs to the next calendar year's fiscal year.
317	     */
318	    public static int fiscalYearOf(LocalDate date) {
319	        return date.getMonthValue() >= FISCAL_YEAR_START_MONTH ? date.getYear() + 1 : date.getYear();
320	    }
321	
322	    /**
323	     * The fiscal year of the owner's (business-day-adjusted) {@code registrationDate}, formatted
324	     * {@code 'FY<YY>'} where YY is the last two digits of the fiscal year (see
325	     * {@link #fiscalYearOf(LocalDate)}). Null when no registration date is set.
326	     */
327	    public String getFiscalYear() {
328	        if (this.registrationDate == null) {
329	            return null;
330	        }
331	        return String.format("FY%02d", fiscalYearOf(this.registrationDate) % 100);
332	    }
333	
334	    /**
335	     * The owner's membership points, computed from stored fields: they start at 0, gain 2 when an
336	     * email is present, gain 1 when {@code namesakeCount} is 0, gain 2 for a household of
337	     * {@value #MEMBERSHIP_HOUSEHOLD_SIZE} or more (see {@link #getHouseholdSize()}), and gain 3 when
338	     * the owner's tenure (fiscal years elapsed since its {@code registrationDate}) is at least
339	     * {@value #MEMBERSHIP_TENURE_FISCAL_YEARS}.
340	     */
341	    public int getMembershipPoints() {
342	        int points = 0;
343	        if (this.email != null && !this.email.isEmpty()) {
344	            points += 2;
345	        }
346	        if (this.namesakeCount != null && this.namesakeCount == 0) {
347	            points += 1;
348	        }
349	        if (this.householdSize >= MEMBERSHIP_HOUSEHOLD_SIZE) {
350	            points += 2;
351	        }
352	        if (this.registrationDate != null
353	                && (fiscalYearOf(LocalDate.now()) - fiscalYearOf(this.registrationDate))
354	                        >= MEMBERSHIP_TENURE_FISCAL_YEARS) {
355	            points += 3;
356	        }
357	        return points;
358	    }
359	
360	    /**
361	     * The owner's numeric membership level, mapped from {@link #getMembershipPoints()}: 1 for 0-1
362	     * points, 2 for 2-3 points, 3 for 4-5 points, and 4 for 6 or more points.
363	     */
364	    public int getMembershipLevel() {
365	        int points = getMembershipPoints();
366	        if (points >= 6) {
367	            return 4;
368	        }
369	        if (points >= 4) {
370	            return 3;
371	        }
372	        if (points >= 2) {
373	            return 2;
374	        }
375	        return 1;
376	    }
377	
378	    /**
379	     * The derived identity key used to detect duplicate owners: the (already normalized) telephone,
380	     * the email or empty, and the {@code householdId} or empty, joined with {@code '|'}. This single
381	     * key consolidates the former separate telephone, email and household duplicate rules — two
382	     * owners are duplicates only when their whole identity keys are equal. Because the telephone is
383	     * part of the key, two members of the same household (same {@code householdId}) with different
384	     * telephones have different keys and are both allowed.
385	     */
386	    public String getIdentityKey() {
387	        String tel = this.telephone == null ? "" : this.telephone;
388	        String mail = this.email == null ? "" : this.email;
389	        String household = this.householdId == null ? "" : this.householdId;
390	        return tel + "|" + mail + "|" + household;
391	    }
392	
393	    /**
394	     * A single Luhn check digit (0-9) computed over the digits contained in {@code customerCode},
395	     * or null when the {@code customerCode} has not been assigned.
396	     */
397	    public Integer getCheckDigit() {
398	        if (this.customerCode == null) {
399	            return null;
400	        }
401	        int sum = 0;
402	        boolean dbl = true;
403	        for (int i = this.customerCode.length() - 1; i >= 0; i--) {
404	            char c = this.customerCode.charAt(i);
405	            if (c < '0' || c > '9') {
406	                continue;
407	            }
408	            int d = c - '0';
409	            if (dbl) {
410	                d *= 2;
411	                if (d > 9) {
412	                    d -= 9;
413	                }
414	            }
415	            sum += d;
416	            dbl = !dbl;
417	        }
418	        return (10 - (sum % 10)) % 10;
419	    }
420	
421	    /**
422	     * The owner's membership number formatted {@code '<customerCode>-M<YY>'} where YY is the last
423	     * two digits of the fiscal year of the {@code registrationDate} (see
424	     * {@link #fiscalYearOf(LocalDate)}), or null when either the {@code customerCode} or the
425	     * {@code registrationDate} is not set.
426	     */
427	    public String getMembershipNumber() {
428	        if (this.customerCode == null || this.registrationDate == null) {
429	            return null;
430	        }
431	        String yy = String.format("%02d", fiscalYearOf(this.registrationDate) % 100);
432	        return this.customerCode + "-M" + yy;
433	    }
434	
435	    public boolean isSharesHousehold() {
436	        return this.sharesHousehold;
437	    }
438	
439	    public void setSharesHousehold(boolean sharesHousehold) {
440	        this.sharesHousehold = sharesHousehold;
441	    }
442	
443	    public int getHouseholdSize() {
444	        return this.householdSize;
445	    }
446	
447	    public void setHouseholdSize(int householdSize) {
448	        this.householdSize = householdSize;
449	    }
450	
451	    protected Set<Pet> getPetsInternal() {
452	        if (this.pets == null) {
453	            this.pets = new HashSet<>();
454	        }
455	        return this.pets;
456	    }
457	
458	    protected void setPetsInternal(Set<Pet> pets) {
459	        this.pets = pets;
460	    }
461	
462	    public List<Pet> getPets() {
463	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
464	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
465	        return Collections.unmodifiableList(sortedPets);
466	    }
467	
468	    public void setPets(List<Pet> pets) {
469	        this.pets = new HashSet<>(pets);
470	    }
471	
472	    public void addPet(Pet pet) {
473	        getPetsInternal().add(pet);
474	        pet.setOwner(this);
475	    }
476	
477	    /**
478	     * Return the Pet with the given name, or null if none found for this Owner.
479	     *
480	     * @param name to test
481	     * @return true if pet name is already in use
482	     */
483	    public Pet getPet(String name) {
484	        return getPet(name, false);
485	    }
486	
487	    /**
488	     * Return the Pet with the given name, or null if none found for this Owner.
489	     *
490	     * @param name to test
491	     * @return true if pet name is already in use
492	     */
493	    public Pet getPet(String name, boolean ignoreNew) {
494	        name = name.toLowerCase();
495	        for (Pet pet : getPetsInternal()) {
496	            if (!ignoreNew || !pet.isNew()) {
497	                String compName = pet.getName();
498	                compName = compName.toLowerCase();
499	                if (compName.equals(name)) {
500	                    return pet;
501	                }
502	            }
503	        }
504	        return null;
505	    }
506	
507	    public Pet getPet(Integer petId) {
508	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
509	    }
510	
511	    @Override
512	    public String toString() {
513	        return new ToStringCreator(this)
514	
515	            .append("id", this.getId())
516	            .append("new", this.isNew())
517	            .append("lastName", this.getLastName())
518	            .append("firstName", this.getFirstName())
519	            .append("address", this.address)
520	            .append("city", this.city)
521	            .append("telephone", this.telephone)
522	            .toString();
523	    }
524	}
