252	    /**
253	     * Rejects saving {@code owner} when it carries a postcode that is out of range for its city's
254	     * region. The postcode is optional: a {@code null} postcode is left untouched. When present it
255	     * is assumed to already be four digits (enforced by request validation); if the owner's city has
256	     * a known region (see {@link Region}), the postcode must fall within that region's range
257	     * ({@link Region#postcodeRange(String)}). A city with no known region accepts any 4-digit
258	     * postcode.
259	     *
260	     * @throws InvalidPostcodeException if the postcode is out of range for the city's region
261	     */
262	    private void assertPostcodeValid(Owner owner) {
263	        String postcode = owner.getPostcode();
264	        if (postcode == null) {
265	            return;
266	        }
267	        String region = Region.forCity(owner.getCity());
268	        int[] range = region == null ? null : Region.postcodeRange(region);
269	        if (range == null) {
270	            return;
271	        }
272	        int value = Integer.parseInt(postcode);
273	        if (value < range[0] || value > range[1]) {
274	            throw new InvalidPostcodeException(postcode, owner.getCity(), region);
275	        }
276	    }
277	
278	    /**
279	     * Rejects saving {@code owner} when it carries a {@code registrationDate} later than the current
280	     * server date. The registration date is optional: a {@code null} date is left untouched (it is
281	     * defaulted to today by {@link #saveOwner(Owner)}). A registration cannot be dated in the future.
282	     *
283	     * @throws FutureRegistrationDateException if the supplied registration date is after today
284	     */
285	    private void assertRegistrationDateNotFuture(Owner owner) {
286	        LocalDate registrationDate = owner.getRegistrationDate();
287	        if (registrationDate == null) {
288	            return;
289	        }
290	        LocalDate today = LocalDate.now();
291	        if (registrationDate.isAfter(today)) {
292	            throw new FutureRegistrationDateException(registrationDate, today);
293	        }
294	    }
295	
296	    /** Email domains rejected as disposable/throwaway addresses. */
297	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS = Set.of(
298	        "mailinator.com", "tempmail.com", "guerrillamail.com");
299	
300	    /**
301	     * Rejects saving {@code owner} when its email's domain is on the disposable-domain blocklist
302	     * ({@link #DISPOSABLE_EMAIL_DOMAINS}). The email is optional: a {@code null} email is left
303	     * untouched. The comparison is case-insensitive on the part after the last {@code '@'}; the
304	     * email has already been lower-cased by {@link #saveOwner(Owner)} before this runs.
305	     *
306	     * @throws DisposableEmailDomainException if the email domain is blocklisted
307	     */
308	    private void assertEmailDomainAllowed(Owner owner) {
309	        String email = owner.getEmail();
310	        if (email == null) {
311	            return;
312	        }
313	        int at = email.lastIndexOf('@');
314	        if (at < 0) {
315	            return;
316	        }
317	        String domain = email.substring(at + 1).toLowerCase(Locale.ROOT);
318	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
319	            throw new DisposableEmailDomainException(domain);
320	        }
321	    }
