323	    @Override
324	    @Transactional
325	    public void saveOwner(Owner owner) throws DataAccessException {
326	        assertPostcodeValid(owner);
327	        assertRegistrationDateNotFuture(owner);
328	        if (owner.getTelephone() != null) {
329	            owner.setTelephone(normalizeTelephone(owner.getTelephone()));
330	        }
331	        if (owner.getEmail() != null) {
332	            owner.setEmail(normalizeEmail(owner.getEmail()));
333	        }
334	        assertEmailDomainAllowed(owner);
335	        applyAddress(owner);
336	        LocalDate effectiveDate = owner.getRegistrationDate() != null ? owner.getRegistrationDate() : LocalDate.now();
337	        owner.setRegistrationDate(rollToBusinessDay(effectiveDate));
338	        if (owner.getCustomerCode() == null) {
339	            owner.setCustomerCode(generateCustomerCode(owner));
340	        }
341	        boolean creating = owner.isNew();
342	        if (creating) {
343	            owner.setNamesakeCount(countNamesakes(owner));
344	            assertDailyCapacity(owner);
345	            assertCityCapacity(owner);
346	        }
347	        assignHouseholdId(owner);
348	        assertIdentityUnique(owner);
349	        if (creating) {
350	            assertHouseholdUnique(owner);
351	        }
352	        ownerRepository.save(owner);
353	        populateHouseholdSize(owner);
354	        if (creating) {
355	            AUDIT.info(
356	                "owner created: id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
357	                owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
358	                owner.getMembershipLevel(), owner.getMembershipNumber());
359	        }
360	    }
361	
362	    /**
363	     * Build a {@code customerCode} formatted {@code '<REGION>-<HASH8>'} where REGION is the region
364	     * code derived from the owner's postcode (see {@link Region#regionForPostcode(String)}) and
365	     * HASH8 is the first 8 upper-case hex characters of the SHA-256 digest over the concatenation of
366	     * the owner's normalized telephone and {@code lastName}. The telephone is already normalized by
367	     * {@link #saveOwner(Owner)} before this runs. The {@code '<REGION>-<HASH8>'} layout is read back
368	     * by {@link Region#regionOfCustomerCode(String)}; keep the two in sync.
369	     */
370	    private String generateCustomerCode(Owner owner) {
371	        String region = Region.regionForPostcode(owner.getPostcode());
372	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
373	        String lastName = owner.getLastName() == null ? "" : owner.getLastName();
374	        String hash8 = sha256UpperHex(telephone + lastName, 8);
375	        return deduplicateCustomerCode(owner, region + "-" + hash8);
376	    }
377	
378	    /**
379	     * Returns {@code base} unchanged when no other owner already holds it; otherwise appends
380	     * {@code '-<n>'} with the smallest {@code n} of 2 or more that makes the result unique among the
381	     * existing owners' {@code customerCode}s. The {@code owner} being saved is excluded from the
382	     * comparison so re-saving it does not treat its own code as a collision.
383	     */
384	    private String deduplicateCustomerCode(Owner owner, String base) {
385	        Set<String> taken = new HashSet<>();
386	        for (Owner existing : ownerRepository.findAll()) {
387	            if (!existing.getId().equals(owner.getId()) && existing.getCustomerCode() != null) {
388	                taken.add(existing.getCustomerCode());
389	            }
390	        }
391	        if (!taken.contains(base)) {
392	            return base;
393	        }
394	        int n = 2;
395	        while (taken.contains(base + "-" + n)) {
396	            n++;
397	        }
398	        return base + "-" + n;
399	    }
400	
401	    /**
402	     * The first {@code chars} upper-case hex characters of the SHA-256 digest of {@code value}'s
403	     * UTF-8 bytes.
404	     */
405	    private static String sha256UpperHex(String value, int chars) {
406	        try {
407	            MessageDigest digest = MessageDigest.getInstance("SHA-256");
408	            byte[] hash = digest.digest(value.getBytes(StandardCharsets.UTF_8));
409	            StringBuilder sb = new StringBuilder(hash.length * 2);
410	            for (byte b : hash) {
411	                sb.append(String.format("%02X", b));
412	            }
413	            return sb.substring(0, chars);
414	        } catch (NoSuchAlgorithmException e) {
415	            throw new IllegalStateException("SHA-256 not available", e);
416	        }
417	    }
418	
419	    /** Maximum number of owners permitted in a single city. */
420	    private static final long CITY_OWNER_LIMIT = 50L;
421	
422	    /**
423	     * Rejects creating {@code owner} when its city already contains {@link #CITY_OWNER_LIMIT} or
424	     * more owners, so no city can grow beyond the capacity limit.
425	     *
426	     * @throws CityOwnerLimitException if the owner's city is already at capacity
427	     */
428	    private void assertCityCapacity(Owner owner) {
429	        if (owner.getCity() == null) {
430	            return;
431	        }
432	        if (countOwnersInCity(owner.getCity()) >= CITY_OWNER_LIMIT) {
433	            throw new CityOwnerLimitException(owner.getCity(), CITY_OWNER_LIMIT);
434	        }
435	    }
436	
437	    /** Fixed public holidays that the business-day roll skips. */
438	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
439	            LocalDate.parse("2026-01-01"), LocalDate.parse("2026-01-26"),
440	            LocalDate.parse("2026-04-25"), LocalDate.parse("2026-12-25"),
441	            LocalDate.parse("2026-12-28"));
442	
443	    /**
444	     * Rolls {@code date} forward to the next business day. A business day is Monday to Friday that is
445	     * not a listed public holiday; Saturdays, Sundays and public holidays are skipped by advancing
446	     * one day at a time until a business day is reached. Business days are returned unchanged.
447	     */
448	    private static LocalDate rollToBusinessDay(LocalDate date) {
449	        while (isWeekend(date) || PUBLIC_HOLIDAYS.contains(date)) {
450	            date = date.plusDays(1);
451	        }
452	        return date;
453	    }
454	
455	    private static boolean isWeekend(LocalDate date) {
456	        switch (date.getDayOfWeek()) {
457	            case SATURDAY:
458	            case SUNDAY:
459	                return true;
460	            default:
461	                return false;
462	        }
463	    }
464	
465	    /** Maximum number of owners permitted to be registered on a single day. */
466	    private static final long DAILY_OWNER_LIMIT = 100L;
467	
468	    /** More than this many owners registered on a single day raises the bulk-signup warning. */
469	    private static final long BULK_SIGNUP_THRESHOLD = 80L;
470	
471	    /**
472	     * Reports whether more than {@link #BULK_SIGNUP_THRESHOLD} owners have already been registered
473	     * today, reusing the same daily accumulation as the per-day create limit ({@link
474	     * #assertDailyCapacity}).
475	     */
476	    @Override
477	    @Transactional(readOnly = true)
478	    public boolean isBulkSignupWarningActive() throws DataAccessException {
479	        return countOwnersRegisteredOn(LocalDate.now()) > BULK_SIGNUP_THRESHOLD;
480	    }
481	
482	    /**
483	     * Rejects creating {@code owner} when its {@code registrationDate} (defaulted to today for a new
484	     * owner) already has {@link #DAILY_OWNER_LIMIT} or more owners registered, so no more than that
485	     * many owners can be created on any single day.
486	     *
487	     * @throws DailyOwnerLimitException if the owner's registration day is already at capacity
488	     */
489	    private void assertDailyCapacity(Owner owner) {
490	        LocalDate date = owner.getRegistrationDate();
491	        if (date == null) {
492	            return;
493	        }
494	        if (countOwnersRegisteredOn(date) >= DAILY_OWNER_LIMIT) {
495	            throw new DailyOwnerLimitException(date, DAILY_OWNER_LIMIT);
496	        }
497	    }
498	
499	    private long countOwnersRegisteredOn(LocalDate date) {
500	        return ownerRepository.findAll().stream()
501	                .filter(existing -> date.equals(existing.getRegistrationDate()))
502	                .count();
503	    }
504	
505	    private long countOwnersInCity(String city) {
506	        String normalized = normalizeHouseholdValue(city);
507	        return ownerRepository.findAll().stream()
508	                .filter(existing -> normalized.equals(normalizeHouseholdValue(existing.getCity())))
509	                .count();
510	    }
511	
512	    /**
513	     * Counts the existing owners that share both {@code firstName} and {@code lastName} with the
514	     * given new {@code owner}, compared case-insensitively (with incidental whitespace collapsed).
515	     * The owner being created is not itself persisted yet, so the result is the number of namesakes
516	     * that already existed before this create.
517	     */
518	    private int countNamesakes(Owner owner) {
519	        String firstName = normalizeHouseholdValue(owner.getFirstName());
520	        String lastName = normalizeHouseholdValue(owner.getLastName());
521	        int count = 0;
522	        for (Owner existing : ownerRepository.findAll()) {
523	            if (!existing.getId().equals(owner.getId())
524	                    && firstName.equals(normalizeHouseholdValue(existing.getFirstName()))
525	                    && lastName.equals(normalizeHouseholdValue(existing.getLastName()))) {
526	                count++;
527	            }
528	        }
529	        return count;
530	    }
531	
532	    private static String normalizeEmail(String email) {
533	        return email == null ? null : email.toLowerCase(Locale.ROOT);
534	    }
535	
536	    /**
537	     * Normalizes whichever address fields {@code owner} supplied and derives the effective flat
538	     * {@code address} from them. The structured form is preferred: when a non-blank
539	     * {@code addressLine1} is present, {@code address} is set to the normalized {@code addressLine1},
540	     * with a single space and the normalized {@code addressLine2} appended when {@code addressLine2}
541	     * is present. Otherwise the flat {@code address} is normalized in place (backward-compatible). The
542	     * structured fields are also stored in their normalized form. Because everything downstream reads
543	     * {@link Owner#getAddress()}, the household hash, postcode validation and locality all see the
544	     * structured value when present and fall back to the flat address otherwise.
545	     */
546	    private static void applyAddress(Owner owner) {
547	        String line1 = normalizeAddress(owner.getAddressLine1());
548	        String line2 = normalizeAddress(owner.getAddressLine2());
549	        owner.setAddressLine1(line1);
550	        owner.setAddressLine2(line2);
551	        if (line1 != null && !line1.isEmpty()) {
552	            String composed = (line2 != null && !line2.isEmpty()) ? line1 + " " + line2 : line1;
553	            owner.setAddress(composed);
554	        } else if (owner.getAddress() != null) {
555	            owner.setAddress(normalizeAddress(owner.getAddress()));
556	        }
557	    }
558	
559	    /** Common street-type abbreviations expanded during address normalization. */
560	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
561	        "ST", "STREET",
562	        "RD", "ROAD",
563	        "AVE", "AVENUE");
564	
565	    /**
566	     * Canonicalizes a postal address: trims and collapses runs of whitespace into a single space,
567	     * upper-cases, and expands common street-type abbreviations (ST->STREET, RD->ROAD, AVE->AVENUE)
568	     * as whole words. Returns {@code null} for a {@code null} input and an empty string when the
569	     * address is blank once whitespace is stripped, so the required-field check sees the normalized
570	     * form.
571	     */
572	    private static String normalizeAddress(String address) {
573	        if (address == null) {
574	            return null;
575	        }
576	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
577	        if (collapsed.isEmpty()) {
578	            return "";
579	        }
580	        String[] tokens = collapsed.split(" ");
581	        StringBuilder sb = new StringBuilder(collapsed.length());
582	        for (int i = 0; i < tokens.length; i++) {
583	            if (i > 0) {
584	                sb.append(' ');
585	            }
586	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
587	        }
588	        return sb.toString();
589	    }
590	
591	    private static String normalizeTelephone(String telephone) {
592	        return telephone == null ? null : E164Telephone.toE164(telephone);
593	    }
594	
595	    /**
596	     * Rejects saving {@code owner} when its whole {@link Owner#getIdentityKey() identity key} equals
597	     * that of another owner. This single check consolidates the former separate telephone, email and
598	     * household duplicate rules: because the normalized telephone is part of the key, two members of
599	     * the same household (same {@code householdId}) with different telephones have different keys and
600	     * are both allowed — only an exact full-key match is a duplicate.
601	     *
602	     * @throws DuplicateIdentityException if another owner already has the same identity key
603	     */
604	    private void assertIdentityUnique(Owner owner) {
605	        String identityKey = owner.getIdentityKey();
606	        for (Owner existing : ownerRepository.findAll()) {
607	            if (!existing.getId().equals(owner.getId()) && !existing.isDeleted()
608	                    && identityKey.equals(existing.getIdentityKey())) {
609	                throw new DuplicateIdentityException(identityKey);
610	            }
611	        }
612	    }
613	
614	    /**
615	     * Assigns {@code owner} its deterministic {@code householdId}: the first 12 upper-case hex
616	     * characters of the SHA-256 digest over {@code normalizedLastName + '|' + postcode}, so all
617	     * owners that share a normalized {@code lastName} and {@code postcode} automatically share the
618	     * same household. Left {@code null} when either the lastName or the postcode is absent, since a
619	     * household is keyed on both.
620	     */
621	    private void assignHouseholdId(Owner owner) {
622	        String lastName = normalizeHouseholdValue(owner.getLastName());
623	        String postcode = owner.getPostcode();
624	        if (lastName.isEmpty() || postcode == null || postcode.isBlank()) {
625	            owner.setHouseholdId(null);
626	            return;
627	        }
628	        owner.setHouseholdId(generateHouseholdId(lastName, postcode));
629	    }
630	
631	    /**
632	     * Rejects creating {@code owner} when another owner already belongs to the same household — i.e.
633	     * shares its computed {@code householdId} (same normalized {@code lastName} and {@code postcode}).
634	     * Because the household is keyed on those two fields, a second such owner is a household
635	     * duplicate unless it declares {@code sharesHousehold}, in which case it is admitted as a
636	     * declared household member (and, being declared, is never a suspected duplicate). No-op when the
637	     * owner has no household id.
638	     *
639	     * @throws HouseholdDuplicateException if another owner already shares the household and the owner
640	     *     did not declare {@code sharesHousehold}
641	     */
642	    private void assertHouseholdUnique(Owner owner) {
643	        String householdId = owner.getHouseholdId();
644	        if (householdId == null || householdId.isBlank() || owner.isSharesHousehold()) {
645	            return;
646	        }
647	        for (Owner existing : ownerRepository.findAll()) {
648	            if (!existing.getId().equals(owner.getId()) && !existing.isDeleted()
649	                    && householdId.equals(existing.getHouseholdId())) {
650	                throw new HouseholdDuplicateException(householdId);
651	            }
652	        }
653	    }
654	
655	    /**
656	     * Stamps {@code owner} with the number of owners sharing its {@code householdId} (see {@link
657	     * Owner#getHouseholdSize()}), so presentation code can derive the membership tier without
658	     * reaching into the data store. A {@code null} owner or one without a household id is left at
659	     * size 0.
660	     */
661	    private void populateHouseholdSize(Owner owner) {
662	        if (owner == null) {
663	            return;
664	        }
665	        String householdId = owner.getHouseholdId();
666	        if (householdId == null || householdId.isBlank()) {
667	            owner.setHouseholdSize(0);
668	            return;
669	        }
670	        int count = 0;
671	        for (Owner existing : ownerRepository.findAll()) {
672	            if (householdId.equals(existing.getHouseholdId())) {
673	                count++;
674	            }
675	        }
676	        owner.setHouseholdSize(count);
677	    }
678	
679	    /**
680	     * Stamps every owner in {@code owners} with its household size in a single pass over the data
681	     * store, so a list/page of owners is counted without a per-owner query.
682	     *
683	     * @see #populateHouseholdSize(Owner)
684	     */
685	    private void populateHouseholdSizes(Collection<Owner> owners) {
686	        if (owners.isEmpty()) {
687	            return;
688	        }
689	        Map<String, Integer> sizes = new HashMap<>();
690	        for (Owner existing : ownerRepository.findAll()) {
691	            String householdId = existing.getHouseholdId();
692	            if (householdId != null && !householdId.isBlank()) {
693	                sizes.merge(householdId, 1, Integer::sum);
694	            }
695	        }
696	        for (Owner owner : owners) {
697	            String householdId = owner.getHouseholdId();
698	            owner.setHouseholdSize(householdId == null ? 0 : sizes.getOrDefault(householdId, 0));
699	        }
700	    }
701	
702	    /**
703	     * Derives the deterministic {@code householdId} from the normalized {@code lastName} and
704	     * {@code postcode}: the first 12 upper-case hex characters of SHA-256 over
705	     * {@code lastName + '|' + postcode}, so all owners in the same household share the same
706	     * identifier.
707	     */
708	    private static String generateHouseholdId(String lastName, String postcode) {
709	        return sha256UpperHex(lastName + "|" + postcode, 12);
710	    }
711	
712	    /**
713	     * Normalizes a household comparison value by trimming, collapsing runs of whitespace into a
714	     * single space and lower-casing, so comparisons ignore case and incidental whitespace.
715	     */
716	    private static String normalizeHouseholdValue(String value) {
717	        if (value == null) {
718	            return "";
719	        }
720	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
721	    }
722	
723	    @Override
724	    @Transactional(readOnly = true)
725	    public Collection<Owner> findOwnerByLastName(String lastName) throws DataAccessException {
726	        Collection<Owner> owners = ownerRepository.findByLastName(lastName);
727	        populateHouseholdSizes(owners);
728	        return owners;
729	    }
730	
731	    @Override
732	    @Transactional(readOnly = true)
733	    public Collection<Visit> findVisitsByPetId(int petId) {
734	        return visitRepository.findByPetId(petId);
735	    }
736	
737	    @Override
738	    @Transactional(readOnly = true)
739	    public List<Specialty> findSpecialtiesByNameIn(Set<String> names) {
740	        return findEntityById(() -> specialtyRepository.findSpecialtiesByNameIn(names));
741	    }
742	
743	    private <T> T findEntityById(Supplier<T> supplier) {
744	        try {
745	            return supplier.get();
746	        } catch (ObjectRetrievalFailureException | EmptyResultDataAccessException e) {
747	            // Just ignore not found exceptions for Jdbc/Jpa realization
748	            return null;
749	        }
750	    }
751	
752	}
